{"code": "import urllib.request
import urllib.parse
import json

# Try a different approach - use a User-Agent header
url = "https://en.wikipedia.org/w/api.php"

params = {
    'action': 'query',
    'prop': 'revisions',
    'titles': 'Legume',
    'rvstart': '2022-01-01T00:00:00Z',
    'rvend': '2022-11-30T23:59:59Z',
    'rvprop': 'timestamp|user|comment|tags',
    'rvlimit': 500,
    'format': 'json'
}

query_string = urllib.parse.urlencode(params)
full_url = f"{url}?{query_string}"

print(f"Attempting to query: {full_url[:100]}...")

try:
    # Add User-Agent header
    req = urllib.request.Request(
        full_url,
        headers={
            'User-Agent': 'PythonWikipediaBot/1.0 (https://example.com; contact@example.com)'
        }
    )

    with urllib.request.urlopen(req) as response:
        data = json.loads(response.read().decode('utf-8'))
        print("Successfully retrieved data!")
        print(f"\nAPI Response keys: {list(data.keys())}")

